import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard() {
  const [file, setFile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [type, setType] = useState("");
  const [darkMode, setDarkMode] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [loading, setLoading] = useState(false);

  const [showProfile, setShowProfile] = useState(false);
  const [showTheme, setShowTheme] = useState(false);

  const [profile, setProfile] = {
    name: "User",
    email: "user@email.com"
  };

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("profile"));
    if (saved) setProfile(saved);
  }, []);

  const detectSource = (transactions) => {
    if (!transactions.length) return "Not uploaded";

    const text = transactions.map(t => t.description?.toLowerCase() || "").join(" ");

    if (text.includes("upi")) return "GPay";
    if (text.includes("hdfc")) return "HDFC Bank";

    return "Bank Statement";
  };

  const handleUpload = async () => {
    if (!file) return alert("Select file");

    setLoading(true);

    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://localhost:8000/upload-statement/", {
      method: "POST",
      body: formData
    });

    const data = await res.json();

    setTransactions(data.transactions || []);
    setType(detectSource(data.transactions));

    const history = JSON.parse(localStorage.getItem("history")) || [];

    history.unshift({
      date: new Date().toLocaleString(),
      type: detectSource(data.transactions),
      count: data.transactions?.length || 0,
      transactions: data.transactions
    });

    localStorage.setItem("history", JSON.stringify(history));

    setLoading(false);
  };

  const deleteHistory = (i) => {
    const history = JSON.parse(localStorage.getItem("history")) || [];
    history.splice(i, 1);
    localStorage.setItem("history", JSON.stringify(history));
    setActiveTab("history");
  };

  return (
    <div className={`dashboard-main ${darkMode ? "dark" : ""}`}>
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div>
            <div className="logo">FinSight</div>
            <div style={{ fontSize: "13px", color: "#6b7280" }}>
              Personal Expense Intelligence
            </div>
          </div>

          <div className="nav-actions">

            {/* TABS */}
            <div className="tabs">
              <span
                className={`tab ${activeTab === "overview" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("overview")}
              >
                Overview
              </span>

              <span
                className={`tab ${activeTab === "history" ? "active-tab" : ""}`}
                onClick={() => setActiveTab("history")}
              >
                History
              </span>
            </div>

            {/* PROFILE ICON */}
            <div
              onClick={() => {
                setShowProfile(!showProfile);
                setShowTheme(false);
              }}
              style={{
                width: "40px",
                height: "40px",
                borderRadius: "50%",
                background: "linear-gradient(135deg,#4f6df5,#6a85ff)",
                color: "#fff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
                marginLeft: "12px"
              }}
            >
              {profile.name.charAt(0).toUpperCase()}
            </div>

            {/* THEME BUTTON */}
            <div
              onClick={() => {
                setShowTheme(!showTheme);
                setShowProfile(false);
              }}
              style={{
                width: "36px",
                height: "36px",
                borderRadius: "50%",
                background: "#e5e7eb",
                marginLeft: "12px",
                cursor: "pointer"
              }}
            ></div>

          </div>
        </div>

        {/* THEME DROPDOWN */}
        {showTheme && (
          <div style={{
            position: "absolute",
            top: "70px",
            right: "30px",
            background: "#111",
            color: "#fff",
            borderRadius: "14px",
            padding: "10px",
            width: "160px"
          }}>
            <div
              onClick={() => { setDarkMode(false); setShowTheme(false); }}
              style={{ padding: "10px", cursor: "pointer" }}
            >
              ☀️ Light
            </div>

            <div
              onClick={() => { setDarkMode(true); setShowTheme(false); }}
              style={{ padding: "10px", cursor: "pointer" }}
            >
              🌙 Dark
            </div>
          </div>
        )}

        {/* PROFILE PANEL */}
        {showProfile && (
          <div style={{
            position: "absolute",
            top: "70px",
            right: "90px",
            background: "#fff",
            padding: "20px",
            borderRadius: "12px"
          }}>
            <input
              value={profile.name}
              onChange={(e)=>setProfile({...profile,name:e.target.value})}
            />
            <input
              value={profile.email}
              onChange={(e)=>setProfile({...profile,email:e.target.value})}
              style={{marginTop:"10px"}}
            />
            <button onClick={()=>{
              localStorage.setItem("profile",JSON.stringify(profile));
              setShowProfile(false);
            }}>
              Save
            </button>
          </div>
        )}

        {/* HERO */}
        <div className="hero">
          <h1>
            Welcome, <span style={{ color: "#4f6df5" }}>{profile.name}</span>
          </h1>
        </div>

        {/* OVERVIEW */}
        {activeTab === "overview" && (
          <>
            <div className="kpi-grid">
              <div className="kpi-card">
                <h4>Statement Source</h4>
                <p>{type || "Not uploaded"}</p>
              </div>

              <div className="kpi-card">
                <h4>Total Transactions</h4>
                <p>{transactions.length}</p>
              </div>

              <div className="kpi-card">
                <h4>Status</h4>
                <p>{transactions.length ? "Processed" : "Waiting"}</p>
              </div>
            </div>

            <div className="top-section">
              <div className="card upload-card">
                <h3>Upload Statement</h3>

                <div className="upload-row">
                  <input type="file" onChange={(e)=>setFile(e.target.files[0])}/>
                  <button onClick={handleUpload}>
                    {loading ? "Processing..." : "Analyze Statement"}
                  </button>
                </div>
              </div>

              <div className="card summary-card">
                <h3>Insights Summary</h3>
                <p>AI-powered analysis</p>
              </div>
            </div>
          </>
        )}

        {/* HISTORY */}
        {activeTab === "history" && (
          <div className="card table-card">
            <h3>History</h3>

            <table>
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Source</th>
                  <th>Transactions</th>
                  <th>Actions</th>
                </tr>
              </thead>

              <tbody>
                {(JSON.parse(localStorage.getItem("history")) || []).map((h,i)=>(
                  <tr key={i}>
                    <td>{h.date}</td>
                    <td>{h.type}</td>
                    <td>{h.count}</td>
                    <td>
                      <button onClick={()=>{
                        setTransactions(h.transactions);
                        setType(h.type);
                        setActiveTab("overview");
                      }}>
                        View
                      </button>

                      <button onClick={()=>deleteHistory(i)}>
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

          </div>
        )}

      </div>
    </div>
  );
}

export default Dashboard;
